import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  status: string;
}

export interface CustomerListResponse {
  items: Customer[];
}

export async function listRecords(reason: string): Promise<CustomerListResponse> {
  const response = await toiFetch("customers", '/customers', { reason });
  if (!response.ok) {
    let data: any = {};
    try {
      data = await response.json();
    } catch {
      // ignore JSON parse error
    }
    const error: any = new Error(data.message || `Request failed with status ${response.status}`);
    error.status = response.status;
    error.code = data.code;
    if (response.status === 404 && data.code === 'PROJECT_NOT_FOUND') {
      error.name = 'ToiAccessRevokedError';
    }
    throw error;
  }
  return response.json();
}

export async function getRecord(id: string, reason: string) {
  const response = await toiFetch("customers", '/customers/' + encodeURIComponent(id), { reason });
  return response.json();
}

export async function updateStatus(id: string, status: 'active' | 'inactive' | 'suspended', reason: string) {
  const response = await toiFetch("customers", '/customers/' + encodeURIComponent(id), {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status })
  });
  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listRecords, Customer } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [reasonError, setReasonError] = useState('');
  const [customers, setCustomers] = useState<Customer[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [accessError, setAccessError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) {
      e.preventDefault();
    }

    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      setReasonError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setReasonError('');
    setError(null);
    setAccessError(null);
    setLoading(true);

    try {
      const data = await listRecords(trimmedReason);
      if ((data as any)?.code === 'PROJECT_NOT_FOUND') {
        setAccessError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setCustomers(null);
      } else {
        const items = Array.isArray(data) ? data : ((data as any)?.items ?? []);
        setCustomers(items);
      }
      setHasSearched(true);
    } catch (err: any) {
      setHasSearched(true);
      const isAccessRevoked =
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND');

      if (isAccessRevoked) {
        setAccessError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setCustomers(null);
      } else if (err?.status === 404) {
        // Only resource 404 errors with a different code may show no results.
        setCustomers([]);
      } else {
        setError(err?.message || '조회 중 오류가 발생했습니다.');
        setCustomers(null);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '960px', margin: '0 auto', padding: '32px 16px', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700, margin: 0, color: '#111827' }}>고객 목록</h1>
      </header>

      <section style={{ backgroundColor: '#ffffff', padding: '20px', borderRadius: '8px', border: '1px solid #e5e7eb', marginBottom: '24px' }}>
        <form onSubmit={handleSearch} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <label htmlFor="search-reason" style={{ fontSize: '14px', fontWeight: 600, color: '#374151' }}>
            조회 사유
          </label>
          <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
            <div style={{ flex: 1 }}>
              <TextField
                id="search-reason"
                name="reason"
                aria-label="조회 사유"
                value={reason}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                  setReason(e.target.value);
                  if (reasonError && e.target.value.trim().length >= 5) {
                    setReasonError('');
                  }
                }}
                placeholder="조회 사유를 입력하세요 (최소 5자)"
                style={{ width: '100%', boxSizing: 'border-box' }}
              />
              {reasonError ? (
                <p style={{ margin: '6px 0 0 0', fontSize: '13px', color: '#dc2626' }}>
                  {reasonError}
                </p>
              ) : (
                <p style={{ margin: '6px 0 0 0', fontSize: '12px', color: '#6b7280' }}>
                  최소 5자 이상 입력해 주세요.
                </p>
              )}
            </div>
            <Button
              type="submit"
              disabled={loading}
            >
              조회
            </Button>
          </div>
        </form>
      </section>

      {accessError && (
        <div
          role="alert"
          style={{
            padding: '16px',
            backgroundColor: '#fee2e2',
            color: '#991b1b',
            borderRadius: '8px',
            border: '1px solid #f87171',
            marginBottom: '24px',
            fontSize: '14px',
            fontWeight: 500,
          }}
        >
          {accessError}
        </div>
      )}

      {error && !accessError && (
        <div
          role="alert"
          style={{
            padding: '16px',
            backgroundColor: '#fef2f2',
            color: '#b91c1c',
            borderRadius: '8px',
            border: '1px solid #fca5a5',
            marginBottom: '24px',
            fontSize: '14px',
          }}
        >
          {error}
        </div>
      )}

      {loading && (
        <div role="status" style={{ padding: '32px', textAlign: 'center', color: '#6b7280' }}>
          고객 정보를 불러오는 중입니다...
        </div>
      )}

      {!loading && !accessError && customers !== null && (
        <section style={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e5e7eb', overflow: 'hidden' }}>
          <Table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ backgroundColor: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
                <th style={{ textAlign: 'left', padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#374151' }}>id</th>
                <th style={{ textAlign: 'left', padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#374151' }}>name</th>
                <th style={{ textAlign: 'left', padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#374151' }}>phone</th>
                <th style={{ textAlign: 'left', padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#374151' }}>status</th>
              </tr>
            </thead>
            <tbody>
              {customers.length === 0 ? (
                <tr>
                  <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#6b7280', fontSize: '14px' }}>
                    조회된 고객이 없습니다.
                  </td>
                </tr>
              ) : (
                customers.map((customer) => (
                  <tr key={customer.id} style={{ borderBottom: '1px solid #e5e7eb' }}>
                    <td style={{ padding: '12px 16px', fontSize: '14px', color: '#111827' }}>{customer.id}</td>
                    <td style={{ padding: '12px 16px', fontSize: '14px', color: '#111827' }}>{customer.name}</td>
                    <td style={{ padding: '12px 16px', fontSize: '14px', color: '#111827' }}>{customer.phone}</td>
                    <td style={{ padding: '12px 16px', fontSize: '14px', color: '#111827' }}>
                      <Badge>{customer.status}</Badge>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </Table>
        </section>
      )}

      {!loading && !accessError && !error && !hasSearched && (
        <div style={{ padding: '48px', textAlign: 'center', color: '#6b7280', fontSize: '14px' }}>
          조회 사유를 입력하고 조회 버튼을 눌러주세요.
        </div>
      )}
    </main>
  );
}

