import { useState } from 'react';
import { Button, TextField, Badge } from '@toi/tds';
import { getCustomer, Customer } from './api';

export default function App() {
  const [customerId, setCustomerId] = useState('C001');
  const [reason, setReason] = useState('고객 상세 정보 확인');
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [accessError, setAccessError] = useState<string | null>(null);
  const [notFound, setNotFound] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!isReasonValid) {
      setError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setIsLoading(true);
    setAccessError(null);
    setNotFound(false);
    setError(null);
    setCustomer(null);

    try {
      const data = await getCustomer(customerId, reason.trim());
      setCustomer(data);
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.message === '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요'
      ) {
        setAccessError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (err?.status === 404) {
        setNotFound(true);
      } else {
        setError(err?.message || '고객 정보를 불러오는 중 오류가 발생했습니다.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '640px', margin: '32px auto', padding: '0 16px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ fontSize: '24px', fontWeight: 700, marginBottom: '24px', color: '#0f172a' }}>
        고객 C001 상세 화면
      </h1>

      <form onSubmit={handleSearch} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <div>
          <TextField
            label="고객 ID"
            value={customerId}
            onChange={(e: any) => setCustomerId(e.target.value)}
            placeholder="고객 ID"
          />
        </div>

        <div>
          <TextField
            label="조회 사유"
            value={reason}
            onChange={(e: any) => setReason(e.target.value)}
            placeholder="조회 사유를 5자 이상 입력해 주세요"
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ margin: '6px 0 0', fontSize: '13px', color: '#dc2626' }}>
              조회 사유는 5자 이상 입력해야 합니다.
            </p>
          )}
        </div>

        <div>
          <Button
            type="submit"
            onClick={handleSearch}
            disabled={isLoading || !isReasonValid}
          >
            {isLoading ? '조회 중...' : '조회'}
          </Button>
        </div>
      </form>

      {accessError && (
        <div
          role="alert"
          style={{
            marginTop: '24px',
            padding: '16px',
            borderRadius: '8px',
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            color: '#b91c1c',
            fontWeight: 500
          }}
        >
          {accessError}
        </div>
      )}

      {notFound && (
        <div
          role="status"
          style={{
            marginTop: '24px',
            padding: '16px',
            borderRadius: '8px',
            backgroundColor: '#f8fafc',
            border: '1px solid #e2e8f0',
            color: '#64748b'
          }}
        >
          조회 결과가 없습니다.
        </div>
      )}

      {error && !accessError && (
        <div
          role="alert"
          style={{
            marginTop: '24px',
            padding: '16px',
            borderRadius: '8px',
            backgroundColor: '#fff1f2',
            border: '1px solid #ffe4e6',
            color: '#e11d48'
          }}
        >
          {error}
        </div>
      )}

      {customer && (
        <section
          style={{
            marginTop: '24px',
            padding: '24px',
            borderRadius: '8px',
            border: '1px solid #e2e8f0',
            backgroundColor: '#ffffff',
            boxShadow: '0 1px 3px rgba(0, 0, 0, 0.05)'
          }}
        >
          <h2 style={{ fontSize: '18px', fontWeight: 600, marginBottom: '20px', color: '#1e293b' }}>
            고객 상세 정보
          </h2>

          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: '120px 1fr',
              rowGap: '16px',
              columnGap: '16px',
              margin: 0,
              alignItems: 'center'
            }}
          >
            <dt style={{ fontWeight: 600, color: '#64748b' }}>id</dt>
            <dd style={{ margin: 0, color: '#0f172a' }} data-testid="field-id">
              {String(customer.id ?? '')}
            </dd>

            <dt style={{ fontWeight: 600, color: '#64748b' }}>name</dt>
            <dd style={{ margin: 0, color: '#0f172a' }} data-testid="field-name">
              {String(customer.name ?? '')}
            </dd>

            <dt style={{ fontWeight: 600, color: '#64748b' }}>phone</dt>
            <dd style={{ margin: 0, color: '#0f172a' }} data-testid="field-phone">
              {String(customer.phone ?? '')}
            </dd>

            <dt style={{ fontWeight: 600, color: '#64748b' }}>status</dt>
            <dd style={{ margin: 0, color: '#0f172a' }} data-testid="field-status">
              <Badge>{String(customer.status ?? '')}</Badge>
            </dd>
          </dl>
        </section>
      )}
    </main>
  );
}

