import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  createdAt: string;
  note?: string;
}

export interface ListOrdersResponse {
  items: Order[];
}

export async function listOrders(reason: string): Promise<ListOrdersResponse> {
  const response = await toiFetch('orders', '/orders', { reason });
  if (!response.ok) {
    let errBody: any = null;
    try {
      errBody = await response.json();
    } catch {
      // ignore JSON parse errors
    }

    if (response.status === 404 && errBody?.code !== 'PROJECT_NOT_FOUND') {
      return { items: [] };
    }

    const err: any = new Error(errBody?.message || `HTTP ${response.status}`);
    err.status = response.status;
    err.code = errBody?.code;
    throw err;
  }

  return response.json();
}

import { useState, FormEvent } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listOrders, Order } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [accessError, setAccessError] = useState<string | null>(null);
  const [generalError, setGeneralError] = useState<string | null>(null);

  const handleReasonChange = (e: any) => {
    const val = typeof e === 'string' ? e : (e?.target?.value ?? '');
    setReason(val);
  };

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async (e?: FormEvent) => {
    if (e) {
      e.preventDefault();
    }
    if (!isReasonValid || isLoading) {
      return;
    }

    setIsLoading(true);
    setAccessError(null);
    setGeneralError(null);

    try {
      const data = await listOrders(reason.trim());
      setOrders(data?.items || []);
      setHasSearched(true);
    } catch (err: any) {
      const isAccessRevoked =
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND');

      if (isAccessRevoked) {
        setAccessError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setOrders([]);
      } else if (err?.status === 404) {
        setOrders([]);
        setHasSearched(true);
      } else {
        setGeneralError(err?.message || '주문 목록 조회 중 오류가 발생했습니다.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: 1000, margin: '0 auto', padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>주문 목록</h1>

      <form
        onSubmit={handleSearch}
        style={{ display: 'flex', gap: '0.75rem', alignItems: 'flex-start', margin: '1.5rem 0' }}
      >
        <div style={{ flex: 1 }}>
          <TextField
            label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={handleReasonChange}
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ color: '#dc2626', fontSize: '0.875rem', marginTop: '0.25rem' }}>
              조회 사유는 최소 5자 이상 입력해야 합니다.
            </p>
          )}
        </div>
        <div style={{ paddingTop: '1.5rem' }}>
          <Button type="submit" disabled={!isReasonValid || isLoading}>
            {isLoading ? '조회 중...' : '조회'}
          </Button>
        </div>
      </form>

      {accessError && (
        <div
          role="alert"
          style={{
            padding: '1rem',
            backgroundColor: '#fee2e2',
            color: '#991b1b',
            borderRadius: '4px',
            marginBottom: '1rem'
          }}
        >
          {accessError}
        </div>
      )}

      {generalError && (
        <div
          role="alert"
          style={{
            padding: '1rem',
            backgroundColor: '#fef3c7',
            color: '#92400e',
            borderRadius: '4px',
            marginBottom: '1rem'
          }}
        >
          {generalError}
        </div>
      )}

      {isLoading && (
        <div style={{ padding: '2rem', textAlign: 'center', color: '#4b5563' }}>
          주문 목록을 불러오는 중...
        </div>
      )}

      {!isLoading && !accessError && hasSearched && (
        orders.length === 0 ? (
          <div style={{ padding: '2rem', textAlign: 'center', color: '#6b7280' }}>
            조회된 주문이 없습니다.
          </div>
        ) : (
          <Table>
            <thead>
              <tr>
                <th>id</th>
                <th>customerId</th>
                <th>amount</th>
                <th>status</th>
                <th>createdAt</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((order) => (
                <tr key={order.id}>
                  <td>{order.id}</td>
                  <td>{order.customerId}</td>
                  <td>{order.amount}</td>
                  <td>
                    <Badge>{order.status}</Badge>
                  </td>
                  <td>{order.createdAt}</td>
                </tr>
              ))}
            </tbody>
          </Table>
        )
      )}
    </main>
  );
}

