import React, { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listOrders, Order, ToiAccessRevokedError } from './api';

export default function App() {
  const [status, setStatus] = useState('paid');
  const [reason, setReason] = useState('주문 목록 조회');
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searched, setSearched] = useState(false);

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) {
      e.preventDefault();
    }

    if (reason.trim().length < 5) {
      setError('조회 사유를 5자 이상 입력해주세요.');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const data = await listOrders({
        status: status.trim() || undefined,
        sort: 'amount_desc',
        reason: reason.trim(),
      });
      setOrders(data);
      setSearched(true);
    } catch (err: any) {
      if (
        err instanceof ToiAccessRevokedError ||
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        err?.message?.includes('PROJECT_NOT_FOUND') ||
        err?.message?.includes('이 프로젝트에 접근할 수 없어요')
      ) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setError(err?.message || '주문 목록 조회 중 오류가 발생했습니다.');
      }
      setOrders([]);
      setSearched(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '960px', margin: '0 auto', padding: '32px 16px' }}>
      <h1 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '24px' }}>주문 목록</h1>

      <form
        onSubmit={handleSearch}
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '16px',
          padding: '20px',
          backgroundColor: '#f9fafb',
          borderRadius: '8px',
          border: '1px solid #e5e7eb',
          marginBottom: '24px',
        }}
      >
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 200px' }}>
            <TextField
              label="status"
              value={status}
              onChange={(e) => setStatus(e.target.value)}
              placeholder="paid"
            />
          </div>
          <div style={{ flex: '2 1 300px' }}>
            <TextField
              label="조회 사유"
              value={reason}
              onChange={(e) => {
                setReason(e.target.value);
                if (error && e.target.value.trim().length >= 5) {
                  setError(null);
                }
              }}
              placeholder="조회 사유를 5자 이상 입력하세요"
              helperText={reason.trim().length < 5 ? '조회 사유를 5자 이상 입력해주세요.' : undefined}
            />
          </div>
        </div>

        <div>
          <Button type="submit" disabled={loading}>
            조회
          </Button>
        </div>
      </form>

      {error && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            backgroundColor: '#fee2e2',
            color: '#b91c1c',
            borderRadius: '6px',
            marginBottom: '24px',
            border: '1px solid #fca5a5',
          }}
        >
          {error}
        </div>
      )}

      <Table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #e5e7eb', textAlign: 'left' }}>
            <th style={{ padding: '12px 8px' }}>id</th>
            <th style={{ padding: '12px 8px' }}>amount</th>
            <th style={{ padding: '12px 8px' }}>status</th>
          </tr>
        </thead>
        <tbody>
          {!searched && !loading && (
            <tr>
              <td colSpan={3} style={{ padding: '24px', textAlign: 'center', color: '#6b7280' }}>
                조회 버튼을 눌러 목록을 조회하세요.
              </td>
            </tr>
          )}
          {searched && orders.length === 0 && !error && (
            <tr>
              <td colSpan={3} style={{ padding: '24px', textAlign: 'center', color: '#6b7280' }}>
                조회된 주문이 없습니다.
              </td>
            </tr>
          )}
          {orders.map((order) => (
            <tr key={order.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
              <td style={{ padding: '12px 8px' }}>{order.id}</td>
              <td style={{ padding: '12px 8px' }}>{order.amount}</td>
              <td style={{ padding: '12px 8px' }}>
                <Badge>{order.status}</Badge>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </main>
  );
}

