import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId?: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export interface ListOrdersParams {
  status?: string;
  sort?: string;
  reason: string;
}

export class ToiAccessRevokedError extends Error {
  code: string;
  status: number;

  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
    this.code = 'PROJECT_NOT_FOUND';
    this.status = 404;
  }
}

export async function listOrders({ status, sort = 'amount_desc', reason }: ListOrdersParams): Promise<Order[]> {
  const params = new URLSearchParams();
  if (status && status.trim()) {
    params.set('status', status.trim());
  }
  if (sort) {
    params.set('sort', sort);
  }

  const query = params.toString();
  const path = `/orders${query ? `?${query}` : ''}`;

  let response: Response;
  try {
    response = await toiFetch('orders', path, { reason });
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      err?.status === 404
    ) {
      throw new ToiAccessRevokedError();
    }
    throw err;
  }

  if (!response.ok) {
    let errBody: any = null;
    try {
      errBody = await response.json();
    } catch {
      // ignore
    }

    if (response.status === 404) {
      if (errBody?.code === 'PROJECT_NOT_FOUND') {
        throw new ToiAccessRevokedError();
      }
      // Only resource 404 errors with a different code may show no results.
      return [];
    }

    throw new Error(errBody?.message || `요청 실패 (${response.status})`);
  }

  const data = await response.json();
  if (Array.isArray(data)) {
    return data;
  }
  if (data && Array.isArray(data.items)) {
    return data.items;
  }
  return [];
}

export { listOrders as fetchOrders };

