import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  createdAt?: string;
  note: string;
}

export class ApiError extends Error {
  status: number;
  code?: string;
  constructor(message: string, status: number, code?: string) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
  }
}

export async function getOrder(id: string, reason: string): Promise<Order> {
  const response = await toiFetch('orders', `/orders/${encodeURIComponent(id)}`, { reason });
  if (!response.ok) {
    let errorBody: any = null;
    try {
      errorBody = await response.json();
    } catch {
      // empty
    }
    const error = new ApiError(
      errorBody?.message || `Request failed with status ${response.status}`,
      response.status,
      errorBody?.code
    );
    if (response.status === 404 && errorBody?.code === 'PROJECT_NOT_FOUND') {
      error.name = 'ToiAccessRevokedError';
    }
    throw error;
  }
  return response.json();
}

export const getRecord = getOrder;

export async function listRecords(reason: string) {
  const response = await toiFetch('orders', '/orders', { reason });
  return response.json();
}

import React, { useState } from 'react';
import { Button, TextField, Badge } from '@toi/tds';
import { getOrder, Order } from './api';

export default function App() {
  const [orderId, setOrderId] = useState('O001');
  const [reason, setReason] = useState('주문 상세 정보 확인');
  const [validationError, setValidationError] = useState<string | null>(null);
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [accessRevokedMessage, setAccessRevokedMessage] = useState<string | null>(null);
  const [notFoundMessage, setNotFoundMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();

    if (!orderId.trim()) {
      setValidationError('주문 ID를 입력해 주세요.');
      return;
    }

    if (reason.trim().length < 5) {
      setValidationError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setValidationError(null);
    setAccessRevokedMessage(null);
    setNotFoundMessage(null);
    setErrorMessage(null);
    setLoading(true);

    try {
      const data = await getOrder(orderId.trim(), reason.trim());
      setOrder(data);
    } catch (err: any) {
      setOrder(null);
      if (
        err?.name === 'ToiAccessRevokedError' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (typeof err?.message === 'string' && err.message.includes('PROJECT_NOT_FOUND'))
      ) {
        setAccessRevokedMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (err?.status === 404) {
        setNotFoundMessage('주문 정보를 찾을 수 없습니다.');
      } else {
        setErrorMessage(err?.message || '주문 정보를 불러오는 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '720px', margin: '32px auto', padding: '0 16px', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: '0 0 8px 0' }}>주문 상세 조회</h1>
        <p style={{ color: '#6b7280', margin: 0 }}>주문 번호와 조회 사유를 입력하여 주문 정보를 조회합니다.</p>
      </header>

      <form
        onSubmit={handleSearch}
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '16px',
          padding: '20px',
          backgroundColor: '#f9fafb',
          borderRadius: '8px',
          border: '1px solid #e5e7eb'
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <TextField
            label="주문 ID"
            id="order-id"
            name="orderId"
            aria-label="주문 ID"
            value={orderId}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setOrderId(e.target.value)}
            placeholder="O001"
          />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <TextField
            label="조회 사유"
            id="query-reason"
            name="reason"
            aria-label="조회 사유"
            value={reason}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
              const val = e.target.value;
              setReason(val);
              if (val.trim().length > 0 && val.trim().length < 5) {
                setValidationError('조회 사유를 5자 이상 입력해 주세요.');
              } else {
                setValidationError(null);
              }
            }}
            placeholder="최소 5자 이상 입력해 주세요"
          />
          {validationError && (
            <span role="alert" style={{ fontSize: '13px', color: '#ef4444' }}>
              {validationError}
            </span>
          )}
        </div>

        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '8px' }}>
          <Button
            type="submit"
            disabled={loading || !orderId.trim() || !isReasonValid}
          >
            조회
          </Button>
        </div>
      </form>

      {accessRevokedMessage && (
        <div
          role="alert"
          style={{
            marginTop: '20px',
            padding: '16px',
            backgroundColor: '#fee2e2',
            color: '#b91c1c',
            borderRadius: '6px',
            border: '1px solid #fca5a5'
          }}
        >
          {accessRevokedMessage}
        </div>
      )}

      {notFoundMessage && (
        <div
          style={{
            marginTop: '20px',
            padding: '16px',
            backgroundColor: '#f3f4f6',
            color: '#4b5563',
            borderRadius: '6px',
            textAlign: 'center'
          }}
        >
          {notFoundMessage}
        </div>
      )}

      {errorMessage && (
        <div
          role="alert"
          style={{
            marginTop: '20px',
            padding: '16px',
            backgroundColor: '#fee2e2',
            color: '#b91c1c',
            borderRadius: '6px',
            border: '1px solid #fca5a5'
          }}
        >
          {errorMessage}
        </div>
      )}

      {order && (
        <section
          style={{
            marginTop: '24px',
            backgroundColor: '#ffffff',
            border: '1px solid #e5e7eb',
            borderRadius: '8px',
            overflow: 'hidden'
          }}
        >
          <div style={{ padding: '16px 20px', borderBottom: '1px solid #e5e7eb', backgroundColor: '#f9fafb' }}>
            <h2 style={{ fontSize: '18px', fontWeight: 600, margin: 0 }}>주문 정보</h2>
          </div>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <tbody>
              <tr style={{ borderBottom: '1px solid #e5e7eb' }}>
                <th style={{ width: '160px', padding: '12px 20px', textAlign: 'left', fontWeight: 600, color: '#4b5563', backgroundColor: '#fcfcfc' }}>
                  id
                </th>
                <td style={{ padding: '12px 20px', color: '#111827' }} data-testid="order-id">
                  {order.id}
                </td>
              </tr>
              <tr style={{ borderBottom: '1px solid #e5e7eb' }}>
                <th style={{ width: '160px', padding: '12px 20px', textAlign: 'left', fontWeight: 600, color: '#4b5563', backgroundColor: '#fcfcfc' }}>
                  customerId
                </th>
                <td style={{ padding: '12px 20px', color: '#111827' }} data-testid="order-customerId">
                  {order.customerId}
                </td>
              </tr>
              <tr style={{ borderBottom: '1px solid #e5e7eb' }}>
                <th style={{ width: '160px', padding: '12px 20px', textAlign: 'left', fontWeight: 600, color: '#4b5563', backgroundColor: '#fcfcfc' }}>
                  amount
                </th>
                <td style={{ padding: '12px 20px', color: '#111827' }} data-testid="order-amount">
                  {order.amount}
                </td>
              </tr>
              <tr style={{ borderBottom: '1px solid #e5e7eb' }}>
                <th style={{ width: '160px', padding: '12px 20px', textAlign: 'left', fontWeight: 600, color: '#4b5563', backgroundColor: '#fcfcfc' }}>
                  status
                </th>
                <td style={{ padding: '12px 20px', color: '#111827' }} data-testid="order-status">
                  <Badge>{order.status}</Badge>
                </td>
              </tr>
              <tr>
                <th style={{ width: '160px', padding: '12px 20px', textAlign: 'left', fontWeight: 600, color: '#4b5563', backgroundColor: '#fcfcfc' }}>
                  note
                </th>
                <td style={{ padding: '12px 20px', color: '#111827' }} data-testid="order-note">
                  {order.note ?? ''}
                </td>
              </tr>
            </tbody>
          </table>
        </section>
      )}
    </main>
  );
}

