import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (hostConfig) {
  configureToiFetch(hostConfig);
}

export interface RefundItem {
  id: string;
  orderId: string;
  amount: number;
  status: string;
  reason: string;
}

export interface RefundListResponse {
  items: RefundItem[];
}

export async function listRefunds(reason: string): Promise<RefundItem[]> {
  const currentConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
  if (currentConfig) {
    try {
      configureToiFetch(currentConfig);
    } catch {
      // ignore if already configured
    }
  }

  const response = await toiFetch('refunds', '/refunds', { reason });

  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore json parse error
    }

    if (response.status === 404) {
      if (errorData?.code === 'PROJECT_NOT_FOUND' || errorData?.error?.code === 'PROJECT_NOT_FOUND') {
        const err = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        (err as any).name = 'ToiAccessRevokedError';
        (err as any).code = 'PROJECT_NOT_FOUND';
        (err as any).status = 404;
        throw err;
      }
      // Resource 404 errors with a different code may show no results
      return [];
    }

    throw new Error(errorData?.message || `요청 실패 (${response.status})`);
  }

  const data = await response.json();
  if (Array.isArray(data)) {
    return data;
  }
  if (Array.isArray(data?.items)) {
    return data.items;
  }
  return [];
}

export const listRecords = listRefunds;

import React, { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listRefunds, RefundItem } from './api';

export default function App() {
  const [reason, setReason] = useState('환불 내역 확인');
  const [refunds, setRefunds] = useState<RefundItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async (e?: React.SyntheticEvent) => {
    if (e) {
      e.preventDefault();
    }
    if (!isReasonValid || loading) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const data = await listRefunds(reason.trim());
      setRefunds(data);
      setSearched(true);
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        String(err?.message || '').includes('PROJECT_NOT_FOUND') ||
        String(err?.message || '').includes('멤버에서 제거되었거나 권한이 바뀌었을 수 있어요')
      ) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setError(err?.message || '환불 목록을 조회하는 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main
      style={{
        maxWidth: '1000px',
        margin: '0 auto',
        padding: '32px 24px',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      }}
    >
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700, margin: '0 0 8px 0', color: '#191F28' }}>
          환불 목록
        </h1>
        <p style={{ margin: 0, color: '#8B95A1', fontSize: '14px' }}>
          환불 내역을 조회하고 관리할 수 있습니다.
        </p>
      </header>

      <form
        onSubmit={handleSearch}
        style={{
          display: 'flex',
          gap: '12px',
          alignItems: 'flex-start',
          backgroundColor: '#F9FAFB',
          padding: '20px',
          borderRadius: '12px',
          marginBottom: '24px',
        }}
      >
        <div style={{ flex: 1 }}>
          <TextField
            label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e: any) => {
              const val = e?.target?.value !== undefined ? e.target.value : (typeof e === 'string' ? e : '');
              setReason(val);
            }}
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ color: '#E11D48', fontSize: '13px', margin: '6px 0 0 0' }}>
              조회 사유는 최소 5자 이상 입력해야 합니다.
            </p>
          )}
        </div>
        <div style={{ paddingTop: '24px' }}>
          <Button
            type="submit"
            disabled={!isReasonValid || loading}
            onClick={(e) => {
              e.preventDefault();
              handleSearch();
            }}
          >
            조회
          </Button>
        </div>
      </form>

      {error && (
        <div
          role="alert"
          style={{
            padding: '14px 16px',
            backgroundColor: '#FEE2E2',
            color: '#B91C1C',
            borderRadius: '8px',
            marginBottom: '24px',
            fontSize: '14px',
            lineHeight: 1.5,
          }}
        >
          {error}
        </div>
      )}

      <Table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #E5E8EB', backgroundColor: '#F9FAFB' }}>
            <th style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#4E5968' }}>id</th>
            <th style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#4E5968' }}>orderId</th>
            <th style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#4E5968' }}>amount</th>
            <th style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#4E5968' }}>status</th>
            <th style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#4E5968' }}>reason</th>
          </tr>
        </thead>
        <tbody>
          {refunds.length > 0 ? (
            refunds.map((refund) => (
              <tr key={refund.id} style={{ borderBottom: '1px solid #E5E8EB' }}>
                <td style={{ padding: '12px 16px', fontSize: '14px', color: '#191F28' }}>{refund.id}</td>
                <td style={{ padding: '12px 16px', fontSize: '14px', color: '#191F28' }}>{refund.orderId}</td>
                <td style={{ padding: '12px 16px', fontSize: '14px', color: '#191F28' }}>{refund.amount}</td>
                <td style={{ padding: '12px 16px', fontSize: '14px', color: '#191F28' }}>
                  <Badge>{refund.status}</Badge>
                </td>
                <td style={{ padding: '12px 16px', fontSize: '14px', color: '#191F28' }}>{refund.reason}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td
                colSpan={5}
                style={{
                  textAlign: 'center',
                  padding: '48px 0',
                  color: '#8B95A1',
                  fontSize: '14px',
                }}
              >
                {loading ? '조회 중...' : searched ? '조회된 환불 내역이 없습니다.' : '조회 사유를 입력하고 조회 버튼을 눌러주세요.'}
              </td>
            </tr>
          )}
        </tbody>
      </Table>
    </main>
  );
}

