import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) {
  throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
}
configureToiFetch(hostConfig);

export interface RefundItem {
  id: string;
  orderId?: string;
  amount: number;
  status: 'requested' | 'approved' | 'rejected' | string;
  reason?: string;
}

function handleAccessRevocation(status: number, data: any) {
  if (status === 404 && data?.code === 'PROJECT_NOT_FOUND') {
    const error = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    (error as any).name = 'ToiAccessRevokedError';
    (error as any).code = 'PROJECT_NOT_FOUND';
    (error as any).status = 404;
    throw error;
  }
}

export async function getRefund(id: string, reason: string): Promise<RefundItem> {
  let response: Response;
  try {
    response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, { reason });
  } catch (err: any) {
    if (err?.name === 'ToiAccessRevokedError' || err?.code === 'PROJECT_NOT_FOUND') {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    throw err;
  }

  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore
    }
    handleAccessRevocation(response.status, errorData);
    if (response.status === 404) {
      const notFoundErr = new Error('환불 정보를 찾을 수 없습니다.');
      (notFoundErr as any).code = 'RESOURCE_NOT_FOUND';
      (notFoundErr as any).status = 404;
      throw notFoundErr;
    }
    throw new Error(errorData?.message || `조회에 실패했습니다. (${response.status})`);
  }

  return response.json();
}

export async function updateRefundStatus(
  id: string,
  status: 'approved',
  reason: string
): Promise<RefundItem> {
  let response: Response;
  try {
    response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
      method: 'PATCH',
      reason,
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ status }),
    });
  } catch (err: any) {
    if (err?.name === 'ToiAccessRevokedError' || err?.code === 'PROJECT_NOT_FOUND') {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    throw err;
  }

  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore
    }
    handleAccessRevocation(response.status, errorData);
    throw new Error(errorData?.message || `상태 변경에 실패했습니다. (${response.status})`);
  }

  return response.json();
}

import React, { useState } from 'react';
import { Button, TextField, Badge } from '@toi/tds';
import { getRefund, updateRefundStatus, RefundItem } from './api';

export default function App() {
  const [refundId, setRefundId] = useState('R001');
  const [reason, setReason] = useState('환불 상태 확인 및 승인 검토');
  const [refund, setRefund] = useState<RefundItem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPatching, setIsPatching] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleFetch = async () => {
    if (!isReasonValid) return;
    setIsLoading(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const data = await getRefund(refundId.trim(), reason.trim());
      setRefund(data);
    } catch (err: any) {
      setRefund(null);
      setError(err?.message || '조회 중 오류가 발생했습니다.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleApprove = async () => {
    if (!refund || !isReasonValid) return;
    setIsPatching(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const updated = await updateRefundStatus(refund.id, 'approved', reason.trim());
      setRefund(updated);
      setSuccessMessage('환불이 성공적으로 승인되었습니다.');
    } catch (err: any) {
      setError(err?.message || '승인 처리 중 오류가 발생했습니다.');
    } finally {
      setIsPatching(false);
    }
  };

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
      case 'approved':
        return 'success';
      case 'rejected':
        return 'danger';
      default:
        return 'default';
    }
  };

  return (
    <main style={{ maxWidth: '720px', margin: '32px auto', padding: '0 20px', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', color: '#0f172a', marginBottom: '8px' }}>
          환불 R001 상태 변경
        </h1>
        <p style={{ fontSize: '14px', color: '#64748b', margin: 0 }}>
          환불 상세 내역을 조회하고 승인(approved) 상태로 변경할 수 있습니다.
        </p>
      </header>

      <section
        style={{
          background: '#ffffff',
          borderRadius: '8px',
          border: '1px solid #e2e8f0',
          padding: '20px',
          marginBottom: '20px',
          display: 'flex',
          flexDirection: 'column',
          gap: '16px',
        }}
      >
        <div>
          <TextField
            label="환불 ID"
            value={refundId}
            onChange={(e: any) => setRefundId(typeof e === 'string' ? e : e?.target?.value ?? '')}
            placeholder="환불 ID를 입력하세요 (예: R001)"
          />
        </div>

        <div>
          <TextField
            label="사유 입력"
            value={reason}
            onChange={(e: any) => setReason(typeof e === 'string' ? e : e?.target?.value ?? '')}
            placeholder="사유를 5자 이상 입력하세요"
            helperText={!isReasonValid ? '사유는 최소 5자 이상 입력해야 합니다.' : undefined}
            error={!isReasonValid}
          />
        </div>

        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <Button
            onClick={handleFetch}
            disabled={isLoading || !isReasonValid || !refundId.trim()}
          >
            {isLoading ? '조회 중...' : '조회'}
          </Button>
        </div>
      </section>

      {error && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            marginBottom: '20px',
            backgroundColor: '#fef2f2',
            border: '1px solid #fca5a5',
            borderRadius: '6px',
            color: '#b91c1c',
            fontSize: '14px',
          }}
        >
          {error}
        </div>
      )}

      {successMessage && (
        <div
          role="status"
          style={{
            padding: '12px 16px',
            marginBottom: '20px',
            backgroundColor: '#f0fdf4',
            border: '1px solid #86efac',
            borderRadius: '6px',
            color: '#15803d',
            fontSize: '14px',
          }}
        >
          {successMessage}
        </div>
      )}

      {refund && (
        <section
          style={{
            background: '#ffffff',
            borderRadius: '8px',
            border: '1px solid #e2e8f0',
            padding: '20px',
          }}
        >
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
            <h2 style={{ fontSize: '18px', fontWeight: 'bold', margin: 0, color: '#1e293b' }}>
              환불 상세 정보
            </h2>
            <Button
              onClick={handleApprove}
              disabled={isPatching || !isReasonValid || refund.status === 'approved'}
            >
              {isPatching ? '승인 중...' : '승인'}
            </Button>
          </div>

          <div
            style={{
              display: 'grid',
              gridTemplateColumns: '100px 1fr',
              rowGap: '12px',
              columnGap: '16px',
              fontSize: '15px',
              color: '#334155',
            }}
          >
            <span style={{ fontWeight: 600, color: '#64748b' }}>id</span>
            <span data-testid="refund-id">{refund.id}</span>

            <span style={{ fontWeight: 600, color: '#64748b' }}>amount</span>
            <span data-testid="refund-amount">{refund.amount}</span>

            <span style={{ fontWeight: 600, color: '#64748b' }}>status</span>
            <span data-testid="refund-status">
              <Badge variant={getStatusBadgeVariant(refund.status)}>
                {refund.status}
              </Badge>
            </span>
          </div>
        </section>
      )}
    </main>
  );
}

