import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (hostConfig) {
  try {
    configureToiFetch(hostConfig);
  } catch {
    // ignore if already configured
  }
}

export interface Employee {
  id: string;
  name: string;
  department: string;
  phone: string;
  email: string;
  rrn: string;
  account: string;
  status?: string;
}

export class ToiAccessRevokedError extends Error {
  code = 'PROJECT_NOT_FOUND';
  status = 404;
  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

function ensureConfigured() {
  const currentConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
  if (currentConfig) {
    try {
      configureToiFetch(currentConfig);
    } catch {
      // ignore
    }
  }
}

export async function listEmployees(reason: string): Promise<Employee[]> {
  ensureConfigured();

  try {
    const response = await toiFetch('employees', '/employees', { reason });

    if (!response.ok) {
      let body: any = null;
      try {
        body = await response.json();
      } catch {
        // non-json body
      }

      if (response.status === 404) {
        if (body?.code === 'PROJECT_NOT_FOUND') {
          throw new ToiAccessRevokedError();
        }
        // Only resource 404 errors with a different code may show no results.
        return [];
      }

      throw new Error(body?.message || `요청 실패 (${response.status})`);
    }

    const data = await response.json();
    if (Array.isArray(data)) {
      return data;
    }
    if (data && Array.isArray(data.items)) {
      return data.items;
    }
    return [];
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      (err?.response?.status === 404 && err?.response?.data?.code === 'PROJECT_NOT_FOUND')
    ) {
      throw new ToiAccessRevokedError();
    }
    throw err;
  }
}

export const listRecords = listEmployees;
export const getRecord = async (id: string, reason: string) => {
  ensureConfigured();
  const response = await toiFetch('employees', `/employees/${encodeURIComponent(id)}`, { reason });
  return response.json();
};

