import React, { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { fetchCustomers, fetchOrders, Customer, Order, isAccessRevokedError } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid) {
      setError('사유를 5자 이상 입력해 주세요.');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const [customersRes, ordersRes] = await Promise.all([
        fetchCustomers(reason.trim()),
        fetchOrders(reason.trim()),
      ]);
      setCustomers(customersRes.items || []);
      setOrders(ordersRes.items || []);
      setHasSearched(true);
    } catch (err: unknown) {
      if (isAccessRevokedError(err)) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        const msg = err instanceof Error ? err.message : '조회 중 오류가 발생했습니다.';
        setError(msg);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main style={{ padding: '32px', maxWidth: '1200px', margin: '0 auto', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <style>{`
        table {
          width: 100%;
          border-collapse: collapse;
          background-color: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 8px;
          overflow: hidden;
        }
        th {
          background-color: #f9fafb;
          color: #4b5563;
          font-size: 13px;
          font-weight: 600;
          text-align: left;
          padding: 12px 16px;
          border-bottom: 1px solid #e5e7eb;
        }
        td {
          padding: 12px 16px;
          font-size: 14px;
          color: #1f2937;
          border-bottom: 1px solid #f3f4f6;
        }
        tr:last-child td {
          border-bottom: none;
        }
        tr:hover td {
          background-color: #f9fafb;
        }
      `}</style>

      <h1 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '24px', color: '#111827' }}>
        고객 및 주문 관리
      </h1>

      <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start', marginBottom: '24px' }}>
        <div style={{ flex: 1, maxWidth: '480px' }}>
          <TextField
            label="공통 조회 사유"
            name="reason"
            id="reason"
            aria-label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e: any) => {
              const val = typeof e === 'string' ? e : e?.target?.value ?? '';
              setReason(val);
              if (error && val.trim().length >= 5) {
                setError(null);
              }
            }}
            onKeyDown={(e: React.KeyboardEvent) => {
              if (e.key === 'Enter' && isReasonValid && !isLoading) {
                handleSearch();
              }
            }}
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ color: '#DC2626', fontSize: '12px', margin: '4px 0 0 0' }}>
              사유를 5자 이상 입력해 주세요.
            </p>
          )}
        </div>
        <Button
          onClick={handleSearch}
          disabled={!isReasonValid || isLoading}
          style={{ height: '40px', minWidth: '80px', marginTop: '24px' }}
        >
          조회
        </Button>
      </div>

      {error ? (
        <div
          role="alert"
          style={{
            padding: '16px 20px',
            marginBottom: '24px',
            backgroundColor: '#FEF2F2',
            color: '#B91C1C',
            border: '1px solid #FCA5A5',
            borderRadius: '8px',
            fontSize: '14px',
            fontWeight: '500',
            lineHeight: 1.5,
          }}
        >
          {error}
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '36px' }}>
          <section>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '12px' }}>
              <h2 style={{ fontSize: '18px', fontWeight: '600', color: '#1F2937', margin: 0 }}>
                고객 목록
              </h2>
              {hasSearched && (
                <span style={{ fontSize: '13px', color: '#6B7280' }}>
                  총 {customers.length}명
                </span>
              )}
            </div>
            <Table>
              <thead>
                <tr>
                  <th scope="col">고객 ID (id)</th>
                  <th scope="col">이름 (name)</th>
                  <th scope="col">전화번호 (phone)</th>
                </tr>
              </thead>
              <tbody>
                {!hasSearched ? (
                  <tr>
                    <td colSpan={3} style={{ textAlign: 'center', padding: '32px', color: '#9CA3AF' }}>
                      사유를 입력하고 조회 버튼을 눌러주세요.
                    </td>
                  </tr>
                ) : customers.length === 0 ? (
                  <tr>
                    <td colSpan={3} style={{ textAlign: 'center', padding: '32px', color: '#9CA3AF' }}>
                      고객 내역이 없습니다.
                    </td>
                  </tr>
                ) : (
                  customers.map((customer) => (
                    <tr key={customer.id}>
                      <td data-field="id">{customer.id}</td>
                      <td data-field="name">{customer.name}</td>
                      <td data-field="phone">{customer.phone}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </Table>
          </section>

          <section>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '12px' }}>
              <h2 style={{ fontSize: '18px', fontWeight: '600', color: '#1F2937', margin: 0 }}>
                주문 목록
              </h2>
              {hasSearched && (
                <span style={{ fontSize: '13px', color: '#6B7280' }}>
                  총 {orders.length}건
                </span>
              )}
            </div>
            <Table>
              <thead>
                <tr>
                  <th scope="col">주문 ID (id)</th>
                  <th scope="col">고객 ID (customerId)</th>
                  <th scope="col">금액 (amount)</th>
                  <th scope="col">상태 (status)</th>
                </tr>
              </thead>
              <tbody>
                {!hasSearched ? (
                  <tr>
                    <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#9CA3AF' }}>
                      사유를 입력하고 조회 버튼을 눌러주세요.
                    </td>
                  </tr>
                ) : orders.length === 0 ? (
                  <tr>
                    <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#9CA3AF' }}>
                      주문 내역이 없습니다.
                    </td>
                  </tr>
                ) : (
                  orders.map((order) => (
                    <tr key={order.id}>
                      <td data-field="id">{order.id}</td>
                      <td data-field="customerId">{order.customerId}</td>
                      <td data-field="amount">{order.amount}</td>
                      <td data-field="status">
                        <Badge>{order.status}</Badge>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </Table>
          </section>
        </div>
      )}
    </main>
  );
}

