        <div style={{ flex: 1, maxWidth: '480px' }}>
          <TextField
            label="공통 조회 사유"
            name="reason"
            id="reason"
            aria-label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e: any) => {
