import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) {
  throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
}
configureToiFetch(hostConfig);

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  status?: string;
}

export interface Order {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export class ToiAccessRevokedError extends Error {
  readonly status = 404;
  readonly code = 'PROJECT_NOT_FOUND';

  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

export function isAccessRevokedError(err: unknown): boolean {
  if (!err || typeof err !== 'object') return false;
  const e = err as { name?: string; code?: string; status?: number; message?: string };
  if (e.name === 'ToiAccessRevokedError') return true;
  if (e.code === 'PROJECT_NOT_FOUND') return true;
  if (e.status === 404 && e.code === 'PROJECT_NOT_FOUND') return true;
  if (typeof e.message === 'string' && (e.message.includes('PROJECT_NOT_FOUND') || e.message.includes('이 프로젝트에 접근할 수 없어요'))) return true;
  return false;
}

async function handleResponse<T>(response: Response): Promise<{ items: T[] }> {
  if (!response.ok) {
    let errBody: { code?: string; message?: string } | null = null;
    try {
      errBody = await response.json();
    } catch {
      // response body could not be parsed as json
    }

    if (response.status === 404 && errBody?.code === 'PROJECT_NOT_FOUND') {
      throw new ToiAccessRevokedError();
    }

    // Only resource 404 errors with a different code may show no results.
    if (response.status === 404) {
      return { items: [] };
    }

    const message = errBody?.message || `요청 실패 (${response.status})`;
    const error = new Error(message) as Error & { status?: number; code?: string };
    error.status = response.status;
    error.code = errBody?.code;
    throw error;
  }

  return response.json();
}

export async function fetchCustomers(reason: string): Promise<{ items: Customer[] }> {
  try {
    const response = await toiFetch('customers', '/customers', { reason });
    return await handleResponse<Customer>(response);
  } catch (err: unknown) {
    if (isAccessRevokedError(err)) {
      throw new ToiAccessRevokedError();
    }
    throw err;
  }
}

export async function fetchOrders(reason: string): Promise<{ items: Order[] }> {
  try {
    const response = await toiFetch('orders', '/orders', { reason });
    return await handleResponse<Order>(response);
  } catch (err: unknown) {
    if (isAccessRevokedError(err)) {
      throw new ToiAccessRevokedError();
    }
    throw err;
  }
}

export const listRecords = fetchCustomers;

