import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId?: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export interface OrdersResponse {
  items: Order[];
}

export async function fetchOrders(reason: string): Promise<Order[]> {
  try {
    const response = await toiFetch('orders', '/orders', { reason });

    if (!response.ok) {
      let errorData: any = {};
      try {
        errorData = await response.json();
      } catch {
        // ignore JSON parse failure
      }

      if (response.status === 404 && errorData?.code === 'PROJECT_NOT_FOUND') {
        const error = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        (error as any).name = 'ToiAccessRevokedError';
        (error as any).code = 'PROJECT_NOT_FOUND';
        (error as any).status = 404;
        throw error;
      }

      if (response.status === 404) {
        return [];
      }

      const error = new Error(errorData?.message || `조회 실패: ${response.status}`);
      (error as any).status = response.status;
      (error as any).code = errorData?.code;
      throw error;
    }

    const data: OrdersResponse = await response.json();
    return data.items || [];
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      (typeof err?.message === 'string' && err.message.includes('PROJECT_NOT_FOUND'))
    ) {
      const accessError = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      (accessError as any).name = 'ToiAccessRevokedError';
      (accessError as any).code = 'PROJECT_NOT_FOUND';
      (accessError as any).status = 404;
      throw accessError;
    }
    throw err;
  }
}

import { useState, FormEvent } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { fetchOrders, Order } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handleReasonChange = (e: any) => {
    const val = typeof e === 'string' ? e : (e?.target?.value ?? '');
    setReason(val);
  };

  const handleSearch = async (e?: FormEvent) => {
    if (e) {
      e.preventDefault();
    }
    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      return;
    }

    setLoading(true);
    setErrorMessage(null);

    try {
      const items = await fetchOrders(trimmedReason);
      setOrders(items);
      setSearched(true);
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        (typeof err?.message === 'string' && err.message.includes('PROJECT_NOT_FOUND'))
      ) {
        setErrorMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setErrorMessage(err?.message || '주문 목록을 불러오는 중 오류가 발생했습니다.');
      }
      setOrders([]);
      setSearched(true);
    } finally {
      setLoading(false);
    }
  };

  const isReasonValid = reason.trim().length >= 5;

  return (
    <main style={{ padding: '24px', maxWidth: '960px', margin: '0 auto', fontFamily: 'sans-serif' }}>
      <h1 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '20px' }}>주문 목록</h1>

      <form onSubmit={handleSearch} style={{ marginBottom: '24px' }}>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start', flexWrap: 'wrap' }}>
          <div style={{ flex: '1', minWidth: '280px' }}>
            <label htmlFor="reason-input" style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>
              조회 사유
            </label>
            <TextField
              id="reason-input"
              label="조회 사유"
              placeholder="조회 사유를 5자 이상 입력하세요"
              value={reason}
              onChange={handleReasonChange}
            />
            {reason.length > 0 && !isReasonValid && (
              <p style={{ color: '#e53e3e', fontSize: '13px', marginTop: '6px' }}>
                사유는 5자 이상 입력해야 합니다. (현재 {reason.trim().length}자)
              </p>
            )}
          </div>
          <div style={{ paddingTop: '26px' }}>
            <Button
              type="submit"
              disabled={!isReasonValid || loading}
              onClick={handleSearch}
            >
              {loading ? '조회 중...' : '조회'}
            </Button>
          </div>
        </div>
      </form>

      {errorMessage && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            backgroundColor: '#fee2e2',
            color: '#991b1b',
            borderRadius: '6px',
            marginBottom: '20px'
          }}
        >
          {errorMessage}
        </div>
      )}

      {loading && (
        <div style={{ padding: '24px', textAlign: 'center', color: '#6b7280' }}>
          주문 목록을 불러오는 중입니다...
        </div>
      )}

      {!loading && !errorMessage && searched && orders.length === 0 && (
        <div style={{ padding: '24px', textAlign: 'center', color: '#6b7280' }}>
          조회된 주문이 없습니다.
        </div>
      )}

      {!loading && !errorMessage && searched && orders.length > 0 && (
        <Table>
          <thead>
            <tr>
              <th style={{ textAlign: 'left', padding: '10px' }}>id</th>
              <th style={{ textAlign: 'left', padding: '10px' }}>amount</th>
              <th style={{ textAlign: 'left', padding: '10px' }}>status</th>
            </tr>
          </thead>
          <tbody>
            {orders.map((order) => (
              <tr key={order.id}>
                <td style={{ padding: '10px' }}>{order.id}</td>
                <td style={{ padding: '10px' }}>{order.amount}</td>
                <td style={{ padding: '10px' }}>
                  <Badge>{order.status}</Badge>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </main>
  );
}

