import { Button, TextField, Table, Badge } from '@toi/tds';
import { fetchOrders, Order } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handleReasonChange = (e: any) => {
    const val = typeof e === 'string' ? e : (e?.target?.value ?? '');
    setReason(val);
  };

  const handleSearch = async (e?: FormEvent) => {
    if (e) {
      e.preventDefault();
    }
    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      return;
    }

    setLoading(true);
    setErrorMessage(null);

    try {
      const items = await fetchOrders(trimmedReason);
      setOrders(items);
      setSearched(true);
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        (typeof err?.message === 'string' && err.message.includes('PROJECT_NOT_FOUND'))
      ) {
        setErrorMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setErrorMessage(err?.message || '주문 목록을 불러오는 중 오류가 발생했습니다.');
