import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId?: string;
  amount: number;
  status: string;
  createdAt?: string;
  note?: string;
}

export interface OrdersResponse {
  items: Order[];
}

export async function listOrders(reason: string): Promise<OrdersResponse> {
  let response: Response;
  try {
    response = await toiFetch('orders', '/orders', { reason });
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      err?.message?.includes('PROJECT_NOT_FOUND')
    ) {
      const accessErr = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      (accessErr as any).code = 'PROJECT_NOT_FOUND';
      (accessErr as any).status = 404;
      throw accessErr;
    }
    throw err;
  }

  if (!response.ok) {
    let errorBody: any = null;
    try {
      errorBody = await response.json();
    } catch {
      // ignore
    }

    if (response.status === 404) {
      if (errorBody?.code === 'PROJECT_NOT_FOUND') {
        const accessErr = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        (accessErr as any).code = 'PROJECT_NOT_FOUND';
        (accessErr as any).status = 404;
        throw accessErr;
      }
      // Only resource 404 errors with a different code may show no results.
      return { items: [] };
    }

    const error = new Error(errorBody?.message || `요청 실패 (${response.status})`);
    (error as any).status = response.status;
    (error as any).code = errorBody?.code;
    throw error;
  }

  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { listOrders, Order } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [orders, setOrders] = useState<Order[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleFetch = async () => {
    if (!isReasonValid || loading) return;
    setLoading(true);
    setError(null);

    try {
      const data = await listOrders(reason.trim());
      setOrders(data.items || []);
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.message?.includes('PROJECT_NOT_FOUND') ||
        err?.message?.includes('이 프로젝트에 접근할 수 없어요')
      ) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setError(err?.message || '주문 목록 조회에 실패했습니다.');
      }
      setOrders(null);
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '960px', margin: '0 auto', padding: '32px 16px', fontFamily: 'system-ui, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: '0 0 8px 0' }}>주문 목록</h1>
        <p style={{ color: '#6b7280', margin: 0, fontSize: '14px' }}>
          주문 목록을 조회하려면 사유를 5자 이상 입력하세요.
        </p>
      </header>

      <section
        style={{
          display: 'flex',
          gap: '12px',
          alignItems: 'flex-start',
          marginBottom: '24px',
          padding: '20px',
          background: '#f9fafb',
          borderRadius: '8px',
          border: '1px solid #e5e7eb',
        }}
      >
        <div style={{ flex: 1, minWidth: '260px' }}>
          <TextField
            label="사유 입력"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e: any) => setReason(e?.target?.value ?? e ?? '')}
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ color: '#dc2626', fontSize: '13px', marginTop: '6px', marginBottom: 0 }}>
              사유를 5자 이상 입력해 주세요. (현재 {reason.trim().length}자)
            </p>
          )}
        </div>
        <div style={{ paddingTop: '24px' }}>
          <Button onClick={handleFetch} disabled={!isReasonValid || loading}>
            조회
          </Button>
        </div>
      </section>

      {error && (
        <div
          role="alert"
          style={{
            padding: '16px',
            marginBottom: '24px',
            background: '#fef2f2',
            border: '1px solid #fecaca',
            borderRadius: '6px',
            color: '#b91c1c',
            fontSize: '14px',
          }}
        >
          {error}
        </div>
      )}

      <section style={{ border: '1px solid #e5e7eb', borderRadius: '8px', overflow: 'hidden' }}>
        <Table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ background: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
            <tr>
              <th scope="col" style={{ padding: '12px 16px', fontWeight: 600, color: '#374151' }}>
                id
              </th>
              <th scope="col" style={{ padding: '12px 16px', fontWeight: 600, color: '#374151' }}>
                amount
              </th>
              <th scope="col" style={{ padding: '12px 16px', fontWeight: 600, color: '#374151' }}>
                status
              </th>
              <th scope="col" style={{ padding: '12px 16px', fontWeight: 600, color: '#374151' }}>
                note
              </th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#6b7280' }}>
                  주문 목록을 불러오는 중입니다...
                </td>
              </tr>
            ) : orders === null ? (
              <tr>
                <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#6b7280' }}>
                  사유를 5자 이상 입력한 후 조회 버튼을 눌러주세요.
                </td>
              </tr>
            ) : orders.length === 0 ? (
              <tr>
                <td colSpan={4} style={{ textAlign: 'center', padding: '32px', color: '#6b7280' }}>
                  주문 내역이 없습니다.
                </td>
              </tr>
            ) : (
              orders.map((order) => (
                <tr key={order.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
                  <td style={{ padding: '12px 16px', color: '#111827' }}>{order.id}</td>
                  <td style={{ padding: '12px 16px', color: '#111827' }}>{order.amount}</td>
                  <td style={{ padding: '12px 16px', color: '#111827' }}>{order.status}</td>
                  <td style={{ padding: '12px 16px', color: '#111827' }}>{order.note ?? ''}</td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </section>
    </main>
  );
}

