import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Employee {
  id: string;
  name: string;
  department?: string;
  phone: string;
  email: string;
  rrn: string;
  account: string;
  status?: string;
}

export class ToiAccessRevokedError extends Error {
  status = 404;
  code = 'PROJECT_NOT_FOUND';

  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

export async function listEmployees(reason: string): Promise<Employee[]> {
  let response: Response;
  try {
    response = await toiFetch('employees', '/employees', { reason });
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && (err?.code === 'PROJECT_NOT_FOUND' || err?.message?.includes('PROJECT_NOT_FOUND')))
    ) {
      throw new ToiAccessRevokedError();
    }
    if (err?.status === 404) {
      return [];
    }
    throw err;
  }

  if (!response.ok) {
    let errBody: any = null;
    try {
      errBody = await response.json();
    } catch {
      // ignore
    }

    if (response.status === 404) {
      const code = errBody?.code || errBody?.error?.code;
      if (code === 'PROJECT_NOT_FOUND') {
        throw new ToiAccessRevokedError();
      }
      return [];
    }

    throw new Error(errBody?.message || errBody?.error?.message || `요청 실패 (${response.status})`);
  }

  const data = await response.json();
  return data?.items ?? [];
}

import { useState, type FormEvent } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { listEmployees, type Employee } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async (e?: FormEvent) => {
    if (e) {
      e.preventDefault();
    }
    if (!isReasonValid || loading) {
      return;
    }

    setLoading(true);
    setErrorMessage(null);

    try {
      const items = await listEmployees(reason.trim());
      setEmployees(items);
      setHasSearched(true);
    } catch (err: any) {
      setEmployees([]);
      setHasSearched(false);
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        err?.message?.includes('이 프로젝트에 접근할 수 없어요')
      ) {
        setErrorMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setErrorMessage(err?.message || '조회 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '1.5rem' }}>
        <h1 style={{ fontSize: '1.5rem', fontWeight: 700, margin: '0 0 0.5rem 0' }}>직원 목록 조회</h1>
        <p style={{ color: '#666', margin: 0, fontSize: '0.875rem' }}>
          직원 정보를 조회하려면 최소 5자 이상의 사유를 입력해야 합니다.
        </p>
      </header>

      <form onSubmit={handleSearch} style={{ marginBottom: '1.5rem' }}>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'flex-start', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 320px' }}>
            <label
              htmlFor="query-reason-input"
              style={{ display: 'block', fontSize: '0.875rem', fontWeight: 600, marginBottom: '0.25rem' }}
            >
              조회 사유 (최소 5자)
            </label>
            <TextField
              id="query-reason-input"
              value={reason}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setReason(e.target.value)}
              placeholder="조회 사유를 5자 이상 입력하세요"
            />
            {reason.length > 0 && !isReasonValid && (
              <span style={{ color: '#e53e3e', fontSize: '0.75rem', marginTop: '0.25rem', display: 'block' }}>
                사유는 최소 5자 이상 입력해야 합니다.
              </span>
            )}
          </div>
          <div style={{ paddingTop: '1.5rem' }}>
            <Button
              type="submit"
              onClick={() => handleSearch()}
              disabled={!isReasonValid || loading}
            >
              {loading ? '조회 중...' : '조회'}
            </Button>
          </div>
        </div>
      </form>

      {errorMessage && (
        <div
          role="alert"
          style={{
            padding: '1rem',
            marginBottom: '1.5rem',
            backgroundColor: '#fff5f5',
            color: '#c53030',
            border: '1px solid #feb2b2',
            borderRadius: '4px',
            fontSize: '0.875rem'
          }}
        >
          {errorMessage}
        </div>
      )}

      <section aria-label="직원 목록">
        <Table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#f7fafc', borderBottom: '2px solid #edf2f7' }}>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontWeight: 600, fontSize: '0.875rem' }}>id</th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontWeight: 600, fontSize: '0.875rem' }}>name</th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontWeight: 600, fontSize: '0.875rem' }}>phone</th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontWeight: 600, fontSize: '0.875rem' }}>email</th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontWeight: 600, fontSize: '0.875rem' }}>rrn</th>
              <th style={{ padding: '0.75rem', textAlign: 'left', fontWeight: 600, fontSize: '0.875rem' }}>account</th>
            </tr>
          </thead>
          <tbody>
            {!hasSearched && !errorMessage && (
              <tr>
                <td colSpan={6} style={{ textAlign: 'center', padding: '2rem', color: '#718096' }}>
                  사유를 입력한 후 조회 버튼을 눌러주세요.
                </td>
              </tr>
            )}
            {hasSearched && !errorMessage && employees.length === 0 && (
              <tr>
                <td colSpan={6} style={{ textAlign: 'center', padding: '2rem', color: '#718096' }}>
                  조회된 직원이 없습니다.
                </td>
              </tr>
            )}
            {employees.map((employee) => (
              <tr key={employee.id} style={{ borderBottom: '1px solid #edf2f7' }}>
                <td style={{ padding: '0.75rem', fontSize: '0.875rem' }}>{employee.id}</td>
                <td style={{ padding: '0.75rem', fontSize: '0.875rem' }}>{employee.name}</td>
                <td style={{ padding: '0.75rem', fontSize: '0.875rem' }}>{employee.phone}</td>
                <td style={{ padding: '0.75rem', fontSize: '0.875rem' }}>{employee.email}</td>
                <td style={{ padding: '0.75rem', fontSize: '0.875rem' }}>{employee.rrn}</td>
                <td style={{ padding: '0.75rem', fontSize: '0.875rem' }}>{employee.account}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      </section>
    </main>
  );
}

