import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  status: string;
}

export interface CustomerListResponse {
  items: Customer[];
}

export async function listRecords(reason: string): Promise<CustomerListResponse> {
  const response = await toiFetch("customers", '/customers', { reason });
  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore
    }
    if (response.status === 404) {
      if (errorData?.code === 'PROJECT_NOT_FOUND') {
        const err: any = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        err.name = 'ToiAccessRevokedError';
        err.status = 404;
        err.code = 'PROJECT_NOT_FOUND';
        throw err;
      }
      return { items: [] };
    }
    const err: any = new Error(errorData?.message || `요청 실패 (${response.status})`);
    err.status = response.status;
    err.code = errorData?.code;
    throw err;
  }
  return response.json();
}

export async function getRecord(id: string, reason: string): Promise<Customer> {
  const response = await toiFetch("customers", '/customers/' + encodeURIComponent(id), { reason });
  return response.json();
}

export async function updateStatus(id: string, status: 'active' | 'inactive' | 'suspended', reason: string) {
  const response = await toiFetch("customers", '/customers/' + encodeURIComponent(id), {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status })
  });
  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { listRecords, Customer } from './api';

export default function App() {
  const [reason, setReason] = useState('고객 정보 조회');
  const [items, setItems] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async () => {
    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      setError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const data = await listRecords(trimmedReason);
      const list = Array.isArray(data) ? data : data?.items ?? [];
      setItems(list);
      setHasSearched(true);
    } catch (err: any) {
      if (
        err?.name === 'ToiAccessRevokedError' ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.message === '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요'
      ) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        setItems([]);
        setHasSearched(false);
      } else if (err?.status === 404 && err?.code !== 'PROJECT_NOT_FOUND') {
        setItems([]);
        setHasSearched(true);
      } else {
        setError(err?.message || '고객 목록을 불러오지 못했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ padding: '32px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700, margin: '0 0 8px 0', color: '#191f28' }}>고객 목록</h1>
        <p style={{ margin: 0, color: '#4e5968', fontSize: '14px' }}>등록된 고객 정보를 조회합니다.</p>
      </header>

      <section style={{ marginBottom: '24px', padding: '20px', backgroundColor: '#f9fafb', borderRadius: '8px', border: '1px solid #e5e8eb' }}>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
          <div style={{ flex: 1 }}>
            <TextField
              id="search-reason"
              label="조회 사유"
              value={reason}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                setReason(e.target.value);
                if (error) setError(null);
              }}
              placeholder="조회 사유를 5자 이상 입력하세요"
            />
            {reason.trim().length > 0 && reason.trim().length < 5 && (
              <p style={{ color: '#e53e3e', fontSize: '12px', marginTop: '6px', margin: '6px 0 0 0' }}>
                조회 사유를 5자 이상 입력해 주세요 (최소 5자)
              </p>
            )}
          </div>
          <div style={{ paddingTop: '24px' }}>
            <Button
              onClick={handleSearch}
              disabled={reason.trim().length < 5 || loading}
            >
              {loading ? '조회 중...' : '조회'}
            </Button>
          </div>
        </div>
      </section>

      {error && (
        <div
          role="alert"
          style={{
            padding: '16px',
            marginBottom: '24px',
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            borderRadius: '8px',
            color: '#b91c1c',
            fontSize: '14px',
            fontWeight: 500
          }}
        >
          {error}
        </div>
      )}

      <section style={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e5e8eb', overflow: 'hidden' }}>
        <Table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f2f4f6', borderBottom: '1px solid #e5e8eb' }}>
              <th scope="col" style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#333d4b' }}>id</th>
              <th scope="col" style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#333d4b' }}>name</th>
              <th scope="col" style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#333d4b' }}>phone</th>
              <th scope="col" style={{ padding: '12px 16px', fontSize: '14px', fontWeight: 600, color: '#333d4b' }}>status</th>
            </tr>
          </thead>
          <tbody>
            {!hasSearched ? (
              <tr>
                <td colSpan={4} style={{ padding: '40px 16px', textAlign: 'center', color: '#8b95a1', fontSize: '14px' }}>
                  조회 사유를 입력하고 조회 버튼을 눌러주세요.
                </td>
              </tr>
            ) : items.length === 0 ? (
              <tr>
                <td colSpan={4} style={{ padding: '40px 16px', textAlign: 'center', color: '#8b95a1', fontSize: '14px' }}>
                  조회된 고객이 없습니다.
                </td>
              </tr>
            ) : (
